16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Transient
67	    private boolean bulkSignupWarning;
68	
69	    @Transient
70	    private int householdSize;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    public String getAddress() {
76	        return this.address;
77	    }
78	
79	    public void setAddress(String address) {
80	        this.address = address;
81	    }
82	
83	    public String getCity() {
84	        return this.city;
85	    }
86	
87	    public void setCity(String city) {
88	        this.city = city;
89	    }
90	
91	    public String getTelephone() {
92	        return this.telephone;
93	    }
94	
95	    public void setTelephone(String telephone) {
96	        this.telephone = telephone;
97	    }
98	
99	    public String getEmail() {
100	        return this.email;
101	    }
102	
103	    public void setEmail(String email) {
104	        this.email = email;
105	    }
106	
107	    public LocalDate getRegistrationDate() {
108	        return this.registrationDate;
109	    }
110	
111	    public void setRegistrationDate(LocalDate registrationDate) {
112	        this.registrationDate = registrationDate;
113	    }
114	
115	    public String getCustomerCode() {
116	        return this.customerCode;
117	    }
118	
119	    public void setCustomerCode(String customerCode) {
120	        this.customerCode = customerCode;
121	    }
122	
123	    public String getHouseholdId() {
124	        return this.householdId;
125	    }
126	
127	    public void setHouseholdId(String householdId) {
128	        this.householdId = householdId;
129	    }
130	
131	    public Integer getNamesakeCount() {
132	        return this.namesakeCount;
133	    }
134	
135	    public void setNamesakeCount(Integer namesakeCount) {
136	        this.namesakeCount = namesakeCount;
137	    }
138	
139	    /**
140	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
141	     * Not persisted — derived from {@link #getLastName()} and {@link #getFirstName()}.
142	     */
143	    @Transient
144	    public String getDisplayName() {
145	        return this.getLastName() + ", " + this.getFirstName();
146	    }
147	
148	    /**
149	     * The owner's initials: the upper-cased first letters of firstName and lastName,
150	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
151	     * Not persisted — derived from {@link #getFirstName()} and {@link #getLastName()}.
152	     */
153	    @Transient
154	    public String getInitials() {
155	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
156	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
157	    }
158	
159	    /**
160	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is
161	     * the last two digits of the {@link #getRegistrationDate() registrationDate} year
162	     * (e.g. {@code 'LON-SMI-0007-M26'}).
163	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
164	     */
165	    @Transient
166	    public String getMembershipNumber() {
167	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
168	    }
169	
170	    /**
171	     * The owner's membership tier: {@code 'GOLD'} when the owner's household (owners sharing the
172	     * same {@link #getHouseholdId() householdId}) has 3 or more members; otherwise {@code 'SILVER'}
173	     * when {@link #getNamesakeCount() namesakeCount} is 0 and an {@link #getEmail() email} is
174	     * present, and {@code 'BRONZE'} otherwise.
175	     * Not persisted — derived from {@link #getHouseholdSize()}, {@link #getNamesakeCount()} and
176	     * {@link #getEmail()}.
177	     */
178	    @Transient
179	    public String getMembershipTier() {
180	        if (this.householdSize >= 3) {
181	            return "GOLD";
182	        }
183	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
184	        boolean hasEmail = this.email != null && !this.email.isBlank();
185	        return (uniqueName && hasEmail) ? "SILVER" : "BRONZE";
186	    }
187	
188	    /**
189	     * The number of owners sharing this owner's {@link #getHouseholdId() householdId}, as counted
190	     * when the response was built. Not persisted — assigned for the response by the create and
191	     * fetch pipelines (at least {@code 1}, the owner itself). When no pipeline has populated it the
192	     * field is {@code 0}, which the tier derivation treats as not part of a multi-member household.
193	     */
194	    @Transient
195	    public int getHouseholdSize() {
196	        return this.householdSize;
197	    }
198	
199	    public void setHouseholdSize(int householdSize) {
200	        this.householdSize = householdSize;
201	    }
202	
203	    /**
204	     * Fixed city-to-region table used to derive {@link #getLocality() locality}.
205	     */
206	    private static final Map<String, String> CITY_REGION = Map.of(
207	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
208	
209	    /**
210	     * The owner's locality: the canonical region derived from {@link #getCity() city}
211	     * using the fixed {@link #CITY_REGION} table (Sydney->NSW, Melbourne->VIC,
212	     * Brisbane->QLD), or {@code 'UNKNOWN'} when the city is not in the table.
213	     * Not persisted — derived from {@link #getCity()}.
214	     */
215	    @Transient
216	    public String getLocality() {
217	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
218	    }
219	
220	    /**
221	     * Whether more than 80 owners had already been created today when this response was
222	     * built. Not persisted — populated for the response by the create and fetch pipelines
223	     * and defaults to {@code false} so every owner serialization carries the flag.
224	     */
225	    @Transient
226	    public boolean isBulkSignupWarning() {
227	        return this.bulkSignupWarning;
228	    }
229	
230	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
231	        this.bulkSignupWarning = bulkSignupWarning;
232	    }
233	
234	    protected Set<Pet> getPetsInternal() {
235	        if (this.pets == null) {
236	            this.pets = new HashSet<>();
237	        }
238	        return this.pets;
239	    }
240	
241	    protected void setPetsInternal(Set<Pet> pets) {
242	        this.pets = pets;
243	    }
244	
245	    public List<Pet> getPets() {
246	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
247	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
248	        return Collections.unmodifiableList(sortedPets);
249	    }
250	
251	    public void setPets(List<Pet> pets) {
252	        this.pets = new HashSet<>(pets);
253	    }
254	
255	    public void addPet(Pet pet) {
256	        getPetsInternal().add(pet);
257	        pet.setOwner(this);
258	    }
259	
260	    /**
261	     * Return the Pet with the given name, or null if none found for this Owner.
262	     *
263	     * @param name to test
264	     * @return true if pet name is already in use
265	     */
266	    public Pet getPet(String name) {
267	        return getPet(name, false);
268	    }
269	
270	    /**
271	     * Return the Pet with the given name, or null if none found for this Owner.
272	     *
273	     * @param name to test
274	     * @return true if pet name is already in use
275	     */
276	    public Pet getPet(String name, boolean ignoreNew) {
277	        name = name.toLowerCase();
278	        for (Pet pet : getPetsInternal()) {
279	            if (!ignoreNew || !pet.isNew()) {
280	                String compName = pet.getName();
281	                compName = compName.toLowerCase();
282	                if (compName.equals(name)) {
283	                    return pet;
284	                }
285	            }
286	        }
287	        return null;
288	    }
289	
290	    public Pet getPet(Integer petId) {
291	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
292	    }
293	
294	    @Override
295	    public String toString() {
296	        return new ToStringCreator(this)
297	
298	            .append("id", this.getId())
299	            .append("new", this.isNew())
300	            .append("lastName", this.getLastName())
301	            .append("firstName", this.getFirstName())
302	            .append("address", this.address)
303	            .append("city", this.city)
304	            .append("telephone", this.telephone)
305	            .toString();
306	    }
307	}
